LESSON_DETAILS = {detail['title']: detail for detail in _DETAILS}


def lesson_detail(lesson):
    """Accept a six-field index tuple or title; return its offline reading data."""
    return LESSON_DETAILS[lesson if isinstance(lesson, str) else lesson[0]]


def search_lessons(term):
    """Search complete lesson text, including common errors and exercises."""
    term = str(term).strip().casefold()
    def searchable(lesson):
        detail = lesson_detail(lesson)
        return ' '.join(str(value) for value in detail.values()).casefold()
    return [lesson for lesson in LESSONS if not term or term in searchable(lesson)]
